# the existing array ends right before "let miInit"
m = re.search(r"\n\];\nlet miInit = false;", h)
assert m
h = h[:m.start()] + "\n" + NEW.rstrip('\n') + h[m.start():]
open(p, 'w', encoding='utf8').write(h)

# collect all keys for a verification pass
allkeys = sorted(set(re.findall(r"keys: \[([^\]]*)\]", h) and sum([re.findall(r"'(\d+:\d+)'", k) for k in re.findall(r"keys: \[([^\]]*)\]", h)], [])), key=lambda k: tuple(map(int, k.split(':'))))
open('miracle_keys.json', 'w').write(__import__('json').dumps(allkeys))
mm = re.search(r'<script type="module">([\s\S]*?)</script>', h).group(1)
open('tmp_check.mjs', 'w', encoding='utf8').write(re.sub(r'^import .*$', '', mm, flags=re.M))
print('items:', len(re.findall(r"\{ g: \d, t: '", h)), 'keys:', len(allkeys))
